    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://w3id.org/geolabs/ospd/data-formats/format/fixture-primary-media-type-without-record> ;
            sh:resultMessage "A principal media type is one of the format's observed or inferred media types, whose record gives its source." ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ a sh:SPARQLConstraint ;
                    sh:message "A principal media type is one of the format's observed or inferred media types, whose record gives its source." ;
                    sh:select """
            SELECT $this ?value WHERE {
                $this <https://w3id.org/geolabs/ospd/data-formats/primaryMediaType> ?value .
                FILTER NOT EXISTS {
                    $this <https://w3id.org/geolabs/ospd/data-formats/observedMediaType> | <https://w3id.org/geolabs/ospd/data-formats/inferredMediaType> ?record .
                    ?record <https://w3id.org/geolabs/ospd/data-formats/mediaType> ?value .
                }
            }
        """ ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape df:PrimaryMediaTypeShape ;
            sh:value "application/geo+json" ] .

